input.command:
$roots = @(
  "D:\claude\harness-on-steroids",
  "D:\claude\eval-lab",
  "D:\claude\hades",
  "D:\claude\hades-product",
  "D:\claude\hades-v2",
  "D:\claude\custom-extensions",
  "D:\claude\fossil-core",
  "D:\claude\scc-v2",
  "D:\claude\research-assurance",
  "D:\claude\stupidly-simple-cortex"
)
foreach ($r in $roots) {
  Write-Host "===== $r ====="
  if (Test-Path -LiteralPath $r) {
    git -C $r rev-parse --is-inside-work-tree 2>$null
    git -C $r worktree list 2>&1
  } else {
    Write-Host "MISSING"
  }
  Write-Host ""
}

Get-ChildItem -LiteralPath "D:\claude" -Directory | Where-Object { $_.Name -match "TASK-|PR15|bakeoff|work$|-work" } | ForEach-Object {
  $git = Join-Path $_.FullName ".git"
  $kind = "no-git"
  $branch = ""
  $common = ""
  if (Test-Path -LiteralPath $git) {
    $item = Get-Item -LiteralPath $git -Force
    if ($item.PSIsContainer) { $kind = "repo" } else { $kind = "worktree-file" }
    $branch = (git -C $_.FullName rev-parse --abbrev-ref HEAD 2>$null)
    $common = (git -C $_.FullName rev-parse --git-common-dir 2>$null)
  }
  "{0}`t{1}`t{2}`t{3}`t{4}" -f $_.Name, $_.LastWriteTime.ToString("yyyy-MM-dd HH:mm"), $kind, $branch, $common
}

$paths = @(
  "D:\claude\.git",
  "D:\claude\hades\.git",
  "D:\claude\hades-v2\.git",
  "D:\claude\hades-product\.git",
  "D:\claude\.kilo",
  "D:\claude\hades\.kilo",
  "D:\claude\harness-on-steroids\.kilo"
)
foreach ($p in $paths) {
  if (Test-Path -LiteralPath $p) {
    $i = Get-Item -LiteralPath $p -Force
    $kind = if ($i.PSIsContainer) { "dir" } else { "file" }
    Write-Host "EXISTS $kind $p"
  } else {
    Write-Host "MISSING $p"
  }
}
Write-Host "---- parent remote ----"
git -C "D:\claude" remote -v
Write-Host "---- parent log ----"
git -C "D:\claude" log -1 --format="%h %ci %s"
Write-Host "---- kilo dirs ----"
Get-ChildItem -LiteralPath "D:\claude\.kilo" -Force -ErrorAction SilentlyContinue | Select-Object Mode, Name
Write-Host "---- agent-manager files ----"
Get-ChildItem -LiteralPath "D:\claude" -Recurse -Force -Filter "agent-manager.json" -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName

Write-Host "==== eval-lab task worktree freshness ===="
git -C "D:\claude\eval-lab" worktree list --porcelain | Select-String -Pattern "worktree |branch |HEAD |prunable"
Write-Host ""
Write-Host "==== ahead of main? ===="
$wts = git -C "D:\claude\eval-lab" worktree list --porcelain
$current = $null
foreach ($line in $wts) {
  if ($line -like "worktree *") { $current = $line.Substring(9) }
  if ($line -like "branch *" -and $current) {
    $br = $line.Substring(7)
    $ahead = git -C $current rev-list --count "main..HEAD" 2>$null
    $behind = git -C $current rev-list --count "HEAD..main" 2>$null
    $dirty = git -C $current status --porcelain 2>$null
    $dirtyN = if ($dirty) { ($dirty | Measure-Object).Count } else { 0 }
    $last = git -C $current log -1 --format="%ci" 2>$null
    "{0} | ahead={1} behind={2} dirty={3} last={4} branch={5}" -f (Split-Path $current -Leaf), $ahead, $behind, $dirtyN, $last, $br
  }
}
